 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next((c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] not in {grid[r][j] for r in range(h)
                                       for j in range(w) if j != c}), None)
    if sep is None:
        raise ValueError('separator not found')
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    if len(left[0]) != len(right[0]):
        raise ValueError('panels must have equal width')
    cl = Counter(x for row in left for x in row)
    cr = Counter(x for row in right for x in row)
    bgl, bgr = cl.most_common(1)[0][0], cr.most_common(1)[0][0]
    shared_fg = (set(cl) & set(cr)) - {bgl, bgr}
    if shared_fg:
        # If both panels contain a shared foreground symbol, mark its aligned overlap.
        marker = next(iter(shared_fg))
        return [[3 if left[r][c] == marker and right[r][c] == marker else marker
                 for c in range(len(left[r]))] for r in range(h)]
    if bgl == bgr:
        # Otherwise, keep the shared background color where either panel has a mark;
        # fill locations blank in both panels with 3.
        bg = bgl
        return [[bg if left[r][c] != bg or right[r][c] != bg else 3
                 for c in range(len(left[r]))] for r in range(h)]
    raise ValueError('unrecognized panel color relationship')
